import{_ as l,o as a,c as t,ag as e}from"./chunks/framework.BpFM782D.js";const b=JSON.parse('{"title":"article-writing","description":"","frontmatter":{},"headers":[],"relativePath":"skills/article-writing.md","filePath":"skills/article-writing.md"}'),r={name:"skills/article-writing.md"};function o(d,i,h,n,c,s){return a(),t("div",null,[...i[0]||(i[0]=[e('<h1 id="article-writing" tabindex="-1">article-writing <a class="header-anchor" href="#article-writing" aria-label="Permalink to &quot;article-writing&quot;">​</a></h1><table tabindex="0"><thead><tr><th>欄位</th><th>值</th></tr></thead><tbody><tr><td>名稱</td><td>article-writing</td></tr><tr><td>說明</td><td>技術文章寫作指南。結構化的技術文章撰寫方法論與模板。</td></tr><tr><td>Origin</td><td>ECC</td></tr><tr><td>來源目錄</td><td><code>skills/ecc-article-writing/</code></td></tr></tbody></table><hr><h1 id="文章寫作" tabindex="-1">文章寫作 <a class="header-anchor" href="#文章寫作" aria-label="Permalink to &quot;文章寫作&quot;">​</a></h1><p>撰寫聽起來像真實人類或品牌的長篇內容，而非泛用的 AI 輸出。</p><h2 id="啟動時機" tabindex="-1">啟動時機 <a class="header-anchor" href="#啟動時機" aria-label="Permalink to &quot;啟動時機&quot;">​</a></h2><ul><li>草擬部落格文章、散文、發布貼文、指南、教學或電子報</li><li>將筆記、逐字稿或研究成果轉化為精緻的文章</li><li>從範例中匹配現有創辦人、經營者或品牌的聲音</li><li>優化已撰寫長篇文案的結構、節奏與佐證</li></ul><h2 id="核心規則" tabindex="-1">核心規則 <a class="header-anchor" href="#核心規則" aria-label="Permalink to &quot;核心規則&quot;">​</a></h2><ol><li>從具體的事物開始：範例、輸出、軼事、數字、截圖描述或程式碼區塊。</li><li>在範例之後解釋，而非之前。</li><li>優先使用簡短、直接的句子，避免填充語句。</li><li>有來源時使用具體數字。</li><li>絕不捏造個人傳記事實、公司指標或客戶佐證。</li></ol><h2 id="聲音捕捉工作流程" tabindex="-1">聲音捕捉工作流程 <a class="header-anchor" href="#聲音捕捉工作流程" aria-label="Permalink to &quot;聲音捕捉工作流程&quot;">​</a></h2><p>若使用者想要特定的聲音，請蒐集以下一項或多項：</p><ul><li>已發表的文章</li><li>電子報</li><li>X / LinkedIn 貼文</li><li>文件或備忘錄</li><li>簡短的風格指南</li></ul><p>然後提取：</p><ul><li>句子長度與節奏</li><li>聲音是正式、對話式還是銳利</li><li>偏好的修辭手法，例如括號、列表、片段句或疑問句</li><li>對幽默、意見和反向觀點的接受度</li><li>格式習慣，例如標題、項目符號、程式碼區塊和引述</li></ul><p>若未提供聲音參考，預設使用直接的經營者風格：具體、實用，且不誇大。</p><h2 id="禁止模式" tabindex="-1">禁止模式 <a class="header-anchor" href="#禁止模式" aria-label="Permalink to &quot;禁止模式&quot;">​</a></h2><p>刪除並改寫以下任何內容：</p><ul><li>泛用的開場白，例如「在當今快速演變的格局中」</li><li>填充轉場詞，例如「此外」和「再者」</li><li>誇大詞彙，例如「遊戲規則改變者」、「尖端」或「革命性」</li><li>無佐證的模糊主張</li><li>非由提供情境支撐的個人傳記或信譽聲明</li></ul><h2 id="寫作流程" tabindex="-1">寫作流程 <a class="header-anchor" href="#寫作流程" aria-label="Permalink to &quot;寫作流程&quot;">​</a></h2><ol><li>釐清受眾與目的。</li><li>建立每個區段有一個明確目的的骨架大綱。</li><li>每個區段從佐證、範例或場景開始。</li><li>只在下一句話值得存在時才展開。</li><li>移除任何聽起來像模板或自我吹捧的內容。</li></ol><h2 id="結構指引" tabindex="-1">結構指引 <a class="header-anchor" href="#結構指引" aria-label="Permalink to &quot;結構指引&quot;">​</a></h2><h3 id="技術指南" tabindex="-1">技術指南 <a class="header-anchor" href="#技術指南" aria-label="Permalink to &quot;技術指南&quot;">​</a></h3><ul><li>以讀者能獲得的內容開頭</li><li>每個主要區段使用程式碼或終端機範例</li><li>以具體的重點收尾，而非軟性摘要</li></ul><h3 id="散文-觀點文章" tabindex="-1">散文 / 觀點文章 <a class="header-anchor" href="#散文-觀點文章" aria-label="Permalink to &quot;散文 / 觀點文章&quot;">​</a></h3><ul><li>從張力、矛盾或尖銳的觀察開始</li><li>每個區段維持一條論點主線</li><li>使用能為觀點提供佐證的範例</li></ul><h3 id="電子報" tabindex="-1">電子報 <a class="header-anchor" href="#電子報" aria-label="Permalink to &quot;電子報&quot;">​</a></h3><ul><li>保持第一螢幕的強度</li><li>混合洞見與更新，而非日記填充</li><li>使用清晰的區段標籤與易於瀏覽的結構</li></ul><h2 id="品質門檻" tabindex="-1">品質門檻 <a class="header-anchor" href="#品質門檻" aria-label="Permalink to &quot;品質門檻&quot;">​</a></h2><p>交付前：</p><ul><li>對照提供的來源驗證事實聲明</li><li>移除填充詞與企業語言</li><li>確認聲音符合提供的範例</li><li>確保每個區段都新增了新資訊</li><li>檢查目標平台的格式</li></ul>',30)])])}const q=l(r,[["render",o]]);export{b as __pageData,q as default};
